:myDataset a dcat:Dataset ;
    dqv:hasQualityMeasurement :myDatasetPrecision, :myDatasetAccuracy .

:myDatasetPrecisionAS a dqv:QualityMeasurement ;
     dqv:isMeasurementOf :spatialResolutionAsAngularDistance ;
